import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
		// your code goes here
		Scanner sc = new Scanner(System.in);
		if(!sc.hasNextInt()) return;
		int t = sc.nextInt();
		while(t-->0){
		    int n = sc.nextInt();
		    long[] a = new long[3*n];
		    for(int i = 0;i<3*n;i++){
		        a[i] = sc.nextLong();
		    }
		    Arrays.sort(a);
		    long[] pref = new long[3*n+1];
		    for(int i =0;i<3*n;i++){
		        pref[i+1] = pref[i]+a[3*n-1-i];
		    }
		    long maxStrength = 0;
		    for(int c1 = 0;c1<=n;c1++){
		        int low = 0, high = n-c1;
		        while(high-low>2){
		            int m1 = low+(high-low)/3;
		            int m2 = high-(high-low)/3;
		            if(getScore(c1,m1,n,pref)<getScore(c1,m2,n,pref)){
		                low = m1;
		            }
		            else{
		                high=m2;
		            }
		        }
		        for(int c2 = low;c2<=high;c2++){
		            maxStrength = Math.max(maxStrength,getScore(c1,c2,n,pref));
		        }
		    }
		    System.out.println(maxStrength);
		}

	}
	private static long getScore(int c1,int c2,int n,long[] pref){
	    int k = 3*n-2*c1-c2;
	    return 3*pref[k]+2*pref[c1]+pref[c1+2*c2];
	}
}
